dashboard.definition:
{
  "title": "AI provider setup",
  "description": "Set provider, model, and key, then click SAVE. Search does not open.",
  "defaults": {},
  "inputs": {
    "input_cfg_provider": {
      "type": "input.dropdown",
      "title": "AI provider",
      "options": {
        "token": "tok_cfg_provider",
        "defaultValue": "none",
        "items": [
          {
            "label": "None \u2014 local briefing only",
            "value": "none"
          },
          {
            "label": "OpenAI",
            "value": "openai"
          },
          {
            "label": "Cisco AI Defense",
            "value": "cisco"
          },
          {
            "label": "Azure OpenAI",
            "value": "azure"
          },
          {
            "label": "Anthropic",
            "value": "anthropic"
          },
          {
            "label": "Custom OpenAI-compatible",
            "value": "custom"
          }
        ]
      }
    },
    "input_cfg_model": {
      "type": "input.dropdown",
      "title": "Model",
      "options": {
        "token": "tok_cfg_model",
        "defaultValue": "none",
        "selectFirstSearchResult": true,
        "items": [
          {
            "label": "None \u2014 local briefing only",
            "value": "none"
          },
          {
            "label": "gpt-4o (OpenAI)",
            "value": "gpt-4o"
          },
          {
            "label": "gpt-4o-mini (OpenAI)",
            "value": "gpt-4o-mini"
          },
          {
            "label": "gpt-4.1 (OpenAI)",
            "value": "gpt-4.1"
          },
          {
            "label": "gpt-4.1-mini (OpenAI)",
            "value": "gpt-4.1-mini"
          },
          {
            "label": "o4-mini (OpenAI)",
            "value": "o4-mini"
          },
          {
            "label": "o3 (OpenAI)",
            "value": "o3"
          },
          {
            "label": "gpt-4o (Cisco AI Defense)",
            "value": "gpt-4o"
          },
          {
            "label": "gpt-4o-mini (Cisco AI Defense)",
            "value": "gpt-4o-mini"
          },
          {
            "label": "gpt-4.1 (Cisco AI Defense)",
            "value": "gpt-4.1"
          },
          {
            "label": "gpt-4o (Azure OpenAI)",
            "value": "gpt-4o"
          },
          {
            "label": "gpt-4o-mini (Azure OpenAI)",
            "value": "gpt-4o-mini"
          },
          {
            "label": "gpt-4.1 (Azure OpenAI)",
            "value": "gpt-4.1"
          },
          {
            "label": "Claude Sonnet 5.5 (Anthropic)",
            "value": "claude-sonnet-5-5"
          },
          {
            "label": "Claude Opus 5.5 (Anthropic)",
            "value": "claude-opus-5-5"
          },
          {
            "label": "Claude Haiku 5.5 (Anthropic)",
            "value": "claude-haiku-5-5"
          },
          {
            "label": "Claude Fable 5.1 (Anthropic)",
            "value": "claude-fable-5-1"
          },
          {
            "label": "Claude Haiku 4.5 (Anthropic)",
            "value": "claude-haiku-4-5"
          },
          {
            "label": "gpt-4o (Custom OpenAI-compatible)",
            "value": "gpt-4o"
          },
          {
            "label": "gpt-4o-mini (Custom OpenAI-compatible)",
            "value": "gpt-4o-mini"
          },
          {
            "label": "Llama 3.1 70B (Custom OpenAI-compatible)",
            "value": "llama-3.1-70b"
          },
          {
            "label": "Mixtral 8x7B (Custom OpenAI-compatible)",
            "value": "mixtral-8x7b"
          }
        ]
      },
      "dataSources": {
        "primary": "ds_ai_models"
      }
    },
    "input_cfg_key": {
      "type": "input.text",
      "title": "API key",
      "options": {
        "token": "tok_cfg_key",
        "defaultValue": ""
      }
    },
    "input_cfg_save": {
      "type": "input.text",
      "title": "Save latch (set by SAVE)",
      "options": {
        "token": "tok_cfg_save",
        "defaultValue": "review"
      }
    }
  },
  "dataSources": {
    "ds_ai_current": {
      "type": "ds.chain",
      "name": "Saved AI config",
      "options": {
        "extend": "ds_ai_conn_write",
        "query": "| where 1=0\n| append [\n| makeresults\n| eval stanza=\"default\", mode=\"off\", provider=\"none\", model=\"none\", endpoint=\"none\", api_key=\"none\", inbox_index=\"_internal\", inbox_sourcetype=\"derek_health_ai_unconfigured\", updated_by=\"system\", updated_at=\"0\", note=\"seed\", _seed=1\n| inputlookup append=true dq_agent_ai_config\n| eval stanza=coalesce(stanza, \"default\")\n| eval _seed=coalesce(_seed, 0)\n| eval key_ok=if(isnotnull(api_key) AND api_key!=\"\" AND api_key!=\"none\", 1, 0)\n| eval rank=case(key_ok=1, 3, _seed=0, 2, 1=1, 1)\n| sort 0 -rank\n| dedup stanza\n| where stanza=\"default\"\n| head 1\n| eval _updated=coalesce(tostring(updated_at), \"0\")\n| eval used_ui=if(_updated=\"0\" OR _updated=\"\", 0, 1)\n| eval mode=if(used_ui=0, \"`exec_health_ai_mode`\", coalesce(mode, \"off\"))\n| eval provider=if(used_ui=0, \"`exec_health_ai_provider`\", coalesce(provider, \"none\"))\n| eval model=if(used_ui=0, \"`exec_health_ai_model`\", coalesce(model, \"none\"))\n| eval endpoint=if(used_ui=0, \"`exec_health_ai_endpoint`\", coalesce(endpoint, \"none\"))\n| eval inbox_index=coalesce(inbox_index, \"_internal\")\n| eval inbox_sourcetype=coalesce(inbox_sourcetype, \"derek_health_ai_unconfigured\")\n| lookup dq_agent_ai_providers provider OUTPUT provider_label, default_endpoint, notes\n| eval endpoint=if(endpoint=\"none\" OR endpoint=\"\", coalesce(default_endpoint, \"none\"), endpoint)\n| eval endpoint=if(provider=\"anthropic\" AND NOT match(lower(coalesce(endpoint, \"\")), \"anthropic\"), \"https://api.anthropic.com/v1/messages\", endpoint)\n| eval model=if(provider=\"anthropic\" AND (NOT match(lower(coalesce(model, \"\")), \"^claude\") OR lower(coalesce(model, \"\"))=\"claude-opus-4\" OR match(lower(coalesce(model, \"\")), \"^claude-3-\")), \"claude-haiku-5-5\", model)\n| eval key_state=if(isnotnull(api_key) AND api_key!=\"\" AND api_key!=\"none\", \"SET\", \"MISSING\")\n| eval model_ok=if(isnotnull(model) AND model!=\"\" AND model!=\"none\", 1, 0)\n| eval endpoint_ok=if(isnotnull(endpoint) AND endpoint!=\"\" AND endpoint!=\"none\", 1, 0)\n| eval endpoint_https=if(match(lower(coalesce(endpoint, \"\")), \"^https://[a-z0-9]\"), 1, 0)\n| eval key_shape=if(key_state=\"SET\" AND len(api_key)>=8, \"ok\", \"bad\")\n| eval setup_reason=case(\n    mode!=\"provider\" OR provider=\"none\" OR provider=\"\", \"Local only. No provider is saved.\",\n    key_state!=\"SET\", \"Setup incomplete: API key is missing. Enter a key and click SAVE.\",\n    model_ok=0, \"Setup incomplete: model is missing. Enter a model id and click SAVE.\",\n    endpoint_ok=0, \"Setup incomplete: \".coalesce(provider_label, provider).\" has no endpoint. Set default_endpoint in the provider catalog, then SAVE again.\",\n    1=1, \"Ready. Provider \".coalesce(provider_label, provider).\", model \".model.\", key SET.\")\n| eval ai_status=case(\n    mode!=\"provider\" OR provider=\"none\" OR provider=\"\", \"LOCAL\",\n    key_state=\"SET\" AND model_ok=1 AND endpoint_ok=1, \"READY\",\n    1=1, \"FAILED\")\n| fields - api_key\n| eval finding_id=\"connection_test\"\n| lookup dq_agent_ai_requests finding_id OUTPUT status AS ping_status, requested_at AS ping_at, note AS ping_note, provider AS ping_provider\n| eval ping_match=if(coalesce(ping_provider, \"\") = provider, 1, 0)\n| eval conn_status=case(\n    ai_status=\"LOCAL\", \"SKIP\",\n    ai_status=\"FAILED\", \"FAIL\",\n    key_shape!=\"ok\", \"FAIL\",\n    endpoint_https!=1, \"FAIL\",\n    ping_match=1 AND ping_status=\"replied\", \"PASS\",\n    ping_match=1 AND (ping_status=\"failed\" OR ping_status=\"error\"), \"FAIL\",\n    1=1, \"TESTING\")\n| eval conn_reason=case(\n    conn_status=\"SKIP\", \"No provider is set. Connection test was not run.\",\n    ai_status=\"FAILED\", setup_reason,\n    key_shape!=\"ok\", \"Connection test failed: API key is missing or too short. Enter a key and click SAVE.\",\n    endpoint_https!=1, \"Connection test failed: endpoint is not HTTPS. Set default_endpoint to an https URL in the provider catalog, then SAVE.\",\n    conn_status=\"PASS\" AND provider=\"anthropic\", \"Connection test passed at \".ping_at.\". Anthropic Messages API (https://api.anthropic.com/v1/messages) replied from this search head.\",\n    conn_status=\"PASS\", \"Connection test passed at \".ping_at.\". \".coalesce(provider_label, provider).\" replied from this search head.\",\n    conn_status=\"FAIL\", coalesce(ping_note, \"Connection test failed.\").\" Fix it, then click SAVE to test again.\",\n    1=1, \"No connection test has run for this provider yet. Click SAVE to test.\")\n| eval tile_status=case(conn_status=\"SKIP\", \"LOCAL\", conn_status=\"FAIL\", \"FAILED\", 1=1, conn_status)\n| eval status_color=ai_status\n| eval _color_rank=case(conn_status=\"FAIL\" OR ai_status=\"FAILED\", 1, conn_status=\"TESTING\", 2, 1=1, 3)\n| table setup_reason, ai_status, conn_status, conn_reason, tile_status, status_color, mode, provider, provider_label, model, key_state, endpoint, inbox_index, inbox_sourcetype, notes, _color_rank\n| eval _gate=\"$tok_cfg_save$\"\n]"
      }
    },
    "ds_ai_reason": {
      "type": "ds.chain",
      "name": "Setup reason",
      "options": {
        "extend": "ds_ai_current",
        "query": "| table setup_reason, ai_status, _color_rank"
      }
    },
    "ds_ai_conn_reason": {
      "type": "ds.chain",
      "name": "Connection test reason",
      "options": {
        "extend": "ds_ai_current",
        "query": "| table conn_reason, conn_status, _color_rank"
      }
    },
    "ds_ai_saved": {
      "type": "ds.chain",
      "name": "Saved settings view",
      "options": {
        "extend": "ds_ai_current",
        "query": "| table mode, provider, provider_label, model, key_state, endpoint, inbox_index, inbox_sourcetype, notes, _color_rank"
      }
    },
    "ds_ai_providers": {
      "type": "ds.search",
      "name": "Provider catalog",
      "options": {
        "query": "| inputlookup dq_agent_ai_providers | eval _color_rank=3 | table provider, provider_label, default_endpoint, notes, _color_rank",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_models": {
      "type": "ds.search",
      "name": "Models for selected provider",
      "options": {
        "query": "| inputlookup dq_agent_ai_models\n| eval p=replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\")\n| eval p=if(p=\"\" OR isnull(p), \"none\", p)\n| where provider=p\n| eval label=coalesce(model_label, model), value=model\n| table label, value\n| sort label",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_save": {
      "type": "ds.search",
      "name": "Save control",
      "options": {
        "query": "| makeresults\n| eval p=replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\"), m=replace(\"$tok_cfg_model$\", \"[^A-Za-z0-9._-]\", \"\"), k=len(replace(\"$tok_cfg_key$\", \"[^A-Za-z0-9._/=+-]\", \"\"))\n| eval button_label=\"SAVE\"\n| eval _click_action=\"save|\".p.\"|\".m.\"|\".tostring(k)\n| eval _color_rank=3\n| table button_label, _click_action, _color_rank",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_write": {
      "type": "ds.search",
      "name": "Write AI config",
      "options": {
        "query": "| makeresults\n| eval save=\"$tok_cfg_save$\"\n| eval want=\"save|\".replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\").\"|\".replace(\"$tok_cfg_model$\", \"[^A-Za-z0-9._-]\", \"\").\"|\".tostring(len(replace(\"$tok_cfg_key$\", \"[^A-Za-z0-9._/=+-]\", \"\")))\n| eval stanza=\"default\", _key=\"default\"\n| lookup dq_agent_ai_config stanza OUTPUT inbox_index AS prev_inbox, inbox_sourcetype AS prev_st, endpoint AS prev_endpoint, api_key AS prev_key\n| eval provider=replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\")\n| eval provider=if(provider=\"openai\" OR provider=\"cisco\" OR provider=\"azure\" OR provider=\"anthropic\" OR provider=\"custom\", provider, \"none\")\n| eval model=replace(\"$tok_cfg_model$\", \"[^A-Za-z0-9._-]\", \"\")\n| eval model=if(model=\"\" OR isnull(model), \"none\", model)\n| eval api_key=replace(\"$tok_cfg_key$\", \"[^A-Za-z0-9._/=+-]\", \"\")\n| eval api_key=if(api_key=\"\" OR isnull(api_key) OR api_key=\"none\", coalesce(prev_key, \"none\"), api_key)\n| eval api_key=if(provider=\"none\", \"none\", api_key)\n| where save=want\n| eval mode=if(provider=\"none\", \"off\", \"provider\")\n| lookup dq_agent_ai_providers provider OUTPUT default_endpoint\n| eval endpoint=coalesce(default_endpoint, prev_endpoint, \"none\")\n| eval endpoint=if(provider=\"anthropic\" AND NOT match(lower(coalesce(endpoint, \"\")), \"anthropic\"), \"https://api.anthropic.com/v1/messages\", endpoint)\n| eval model=if(provider=\"anthropic\" AND (NOT match(lower(coalesce(model, \"\")), \"^claude\") OR lower(coalesce(model, \"\"))=\"claude-opus-4\" OR match(lower(coalesce(model, \"\")), \"^claude-3-\")), \"claude-haiku-5-5\", model)\n| eval inbox_index=coalesce(prev_inbox, \"main\")\n| eval inbox_sourcetype=coalesce(prev_st, \"derek_health_ai\")\n| eval updated_by=\"human_dashboard\", updated_at=strftime(now(), \"%Y-%m-%d %H:%M:%S\"), note=\"ui_config\"\n| table _key, stanza, mode, provider, model, endpoint, api_key, inbox_index, inbox_sourcetype, updated_by, updated_at, note\n| appendpipe [\n    | inputlookup append=true dq_agent_ai_config\n    | stats latest(mode) as mode, latest(provider) as provider, latest(model) as model, latest(endpoint) as endpoint, latest(api_key) as api_key, latest(inbox_index) as inbox_index, latest(inbox_sourcetype) as inbox_sourcetype, latest(updated_by) as updated_by, latest(updated_at) as updated_at, latest(note) as note by stanza\n    | eval _key=stanza\n    | outputlookup dq_agent_ai_config\n]\n| where stanza=\"default\"\n| eval key_state=if(api_key!=\"none\" AND api_key!=\"\", \"SET\", \"MISSING\")\n| eval _color_rank=3\n| table updated_at, provider, model, key_state, mode, _color_rank",
        "queryParameters": {
          "earliest": "0",
          "latest": "now"
        }
      }
    },
    "ds_ai_conn_write": {
      "type": "ds.chain",
      "name": "Connection test",
      "options": {
        "extend": "ds_ai_write",
        "query": "| where 1=0\n| append [\n| makeresults\n| eval save=\"$tok_cfg_save$\"\n| eval want=\"save|\".replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\").\"|\".replace(\"$tok_cfg_model$\", \"[^A-Za-z0-9._-]\", \"\").\"|\".tostring(len(replace(\"$tok_cfg_key$\", \"[^A-Za-z0-9._/=+-]\", \"\")))\n| eval stanza=\"default\"\n| lookup dq_agent_ai_config stanza OUTPUT api_key AS prev_key, endpoint AS prev_endpoint\n| eval provider=replace(lower(\"$tok_cfg_provider$\"), \"[^a-z]\", \"\")\n| eval provider=if(provider=\"openai\" OR provider=\"cisco\" OR provider=\"azure\" OR provider=\"anthropic\" OR provider=\"custom\", provider, \"none\")\n| eval model=replace(\"$tok_cfg_model$\", \"[^A-Za-z0-9._-]\", \"\")\n| eval model=if(model=\"\" OR isnull(model), \"none\", model)\n| eval api_key=replace(\"$tok_cfg_key$\", \"[^A-Za-z0-9._/=+-]\", \"\")\n| eval api_key=if(api_key=\"\" OR isnull(api_key) OR api_key=\"none\", coalesce(prev_key, \"none\"), api_key)\n| eval api_key=if(provider=\"none\", \"none\", api_key)\n| lookup dq_agent_ai_providers provider OUTPUT default_endpoint\n| eval endpoint=coalesce(default_endpoint, prev_endpoint, \"none\")\n| eval endpoint=if(provider=\"anthropic\" AND NOT match(lower(coalesce(endpoint, \"\")), \"anthropic\"), \"https://api.anthropic.com/v1/messages\", endpoint)\n| eval model=if(provider=\"anthropic\" AND (NOT match(lower(coalesce(model, \"\")), \"^claude\") OR lower(coalesce(model, \"\"))=\"claude-opus-4\" OR match(lower(coalesce(model, \"\")), \"^claude-3-\")), \"claude-haiku-5-5\", model)\n| eval key_ok=if(isnotnull(api_key) AND api_key!=\"\" AND api_key!=\"none\" AND len(api_key)>=8, 1, 0)\n| eval model_ok=if(model!=\"none\" AND model!=\"\", 1, 0)\n| eval endpoint_ok=if(match(lower(coalesce(endpoint, \"\")), \"^https://[a-z0-9]\"), 1, 0)\n| where save=want AND provider!=\"none\" AND key_ok=1 AND model_ok=1 AND endpoint_ok=1\n| eval finding_id=\"connection_test\", entity=\"ai_setup\", issue=\"connection_test\", actor=\"human_dashboard\"\n| eval requested_at=strftime(now(), \"%Y-%m-%d %H:%M:%S\")\n| eval ai_brief=\"Connection test. Reply with the single word PONG.\"\n| eval is_ping=1\n| derekaiping\n| eval status=if(ai_result=\"replied\", \"replied\", \"failed\")\n| eval note=if(ai_result=\"replied\", \"connection_test ok\", \"connection_test failed: \".coalesce(ai_error, \"no reply\"))\n| eval reply=if(ai_result=\"replied\", ai_reply, \"none\")\n| table finding_id, entity, issue, provider, model, endpoint, status, actor, requested_at, note, ai_brief, reply\n| appendpipe [\n    | inputlookup append=true dq_agent_ai_requests\n    | stats latest(entity) as entity, latest(issue) as issue, latest(provider) as provider, latest(model) as model, latest(endpoint) as endpoint, latest(status) as status, latest(actor) as actor, latest(requested_at) as requested_at, latest(note) as note, latest(ai_brief) as ai_brief, latest(reply) as reply by finding_id\n    | outputlookup dq_agent_ai_requests\n]\n| where finding_id=\"connection_test\"\n| eval _color_rank=if(status=\"replied\", 3, 1)\n| table requested_at, finding_id, provider, status, _color_rank\n]"
      }
    }
  },
  "visualizations": {
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# AI provider setup\nPick an **AI provider**, then a **model** from the dropdown, enter the **API key**, and click **SAVE**. That writes provider config to KV Store on this search head (`dq_agent_ai_config`) and runs a **connection test**. Search does not open. The key is never shown after save and **survives app updates**. Leave key blank to keep the value already stored.",
        "fontSize": "default",
        "backgroundColor": "transparent"
      }
    },
    "viz_status": {
      "type": "splunk.singlevalue",
      "title": "Setup status",
      "dataSources": {
        "primary": "ds_ai_current"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"ai_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"ai_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          },
          {
            "match": "LOCAL",
            "value": "#53A051"
          },
          {
            "match": "READY",
            "value": "#53A051"
          },
          {
            "match": "PROVIDER",
            "value": "#53A051"
          },
          {
            "match": "FAILED",
            "value": "#DC4E41"
          },
          {
            "match": "MISCONFIG",
            "value": "#DC4E41"
          },
          {
            "match": "WAITING",
            "value": "#F8BE34"
          },
          {
            "match": "STALLED",
            "value": "#DC4E41"
          },
          {
            "match": "REPLIED",
            "value": "#53A051"
          },
          {
            "match": "IDLE",
            "value": "#6B6B6B"
          },
          {
            "match": "WAIT",
            "value": "#6B6B6B"
          },
          {
            "match": "PASS",
            "value": "#53A051"
          },
          {
            "match": "TESTING",
            "value": "#F8BE34"
          },
          {
            "match": "SKIP",
            "value": "#6B6B6B"
          },
          {
            "match": "FAIL",
            "value": "#DC4E41"
          }
        ]
      }
    },
    "viz_conn": {
      "type": "splunk.singlevalue",
      "title": "Connection test",
      "dataSources": {
        "primary": "ds_ai_current"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "majorValue": "> primary | seriesByName(\"conn_status\") | lastPoint()",
        "majorColor": "> primary | seriesByName(\"conn_status\") | lastPoint() | matchValue(statusColors)",
        "backgroundColor": "transparent",
        "majorFontSize": 36
      },
      "context": {
        "statusColors": [
          {
            "match": "GREEN",
            "value": "#53A051"
          },
          {
            "match": "YELLOW",
            "value": "#F8BE34"
          },
          {
            "match": "RED",
            "value": "#DC4E41"
          },
          {
            "match": "N/A",
            "value": "#F8BE34"
          },
          {
            "match": "LOCAL",
            "value": "#53A051"
          },
          {
            "match": "READY",
            "value": "#53A051"
          },
          {
            "match": "PROVIDER",
            "value": "#53A051"
          },
          {
            "match": "FAILED",
            "value": "#DC4E41"
          },
          {
            "match": "MISCONFIG",
            "value": "#DC4E41"
          },
          {
            "match": "WAITING",
            "value": "#F8BE34"
          },
          {
            "match": "STALLED",
            "value": "#DC4E41"
          },
          {
            "match": "REPLIED",
            "value": "#53A051"
          },
          {
            "match": "IDLE",
            "value": "#6B6B6B"
          },
          {
            "match": "WAIT",
            "value": "#6B6B6B"
          },
          {
            "match": "PASS",
            "value": "#53A051"
          },
          {
            "match": "TESTING",
            "value": "#F8BE34"
          },
          {
            "match": "SKIP",
            "value": "#6B6B6B"
          },
          {
            "match": "FAIL",
            "value": "#DC4E41"
          }
        ]
      }
    },
    "viz_reason": {
      "type": "splunk.table",
      "title": "Why this status",
      "dataSources": {
        "primary": "ds_ai_reason"
      },
      "showLastUpdated": false,
      "showProgressBar": true,
      "options": {
        "count": 1,
        "showRowNumbers": false,
        "showInternalFields": false,
        "tableFormat": {
          "rowBackgroundColors": "> table | seriesByName(\"_color_rank\") | rangeValue(rowColors)"
        },
        "backgroundColor": "transparent"
      },
      "context": {
        "rowColors": [
          {
            "from": 0,
            "to": 1.5,
